<script setup lang="ts">
import {cloudShopping,shoppingState,syncShopping} from '../services/remoteShopping'
import {computed} from 'vue'
import {store,image,setCartQuantity} from '../stores/community'
import {cartSummary} from '../services/products'
defineProps<{show:boolean}>()
const emit=defineEmits<{'update:show':[value:boolean]}>()
const cart=computed(()=>cartSummary(store.cart))
async function quantity(id:string,value:number){await setCartQuantity(id,value)}
</script>
<template><van-popup :show="show" @update:show="v=>emit('update:show',v)" position="bottom" round closeable><section class="cart-sheet"><h2>我的购物清单</h2><p class="cart-note">{{cloudShopping?'清单按账号同步到云端':'本地加购演示'}} · 未创建订单，不支持支付。</p><p v-if="shoppingState.error" role="alert">{{shoppingState.error}}</p><button v-if="cloudShopping" :disabled="shoppingState.loading" @click="syncShopping().catch(()=>{})">{{shoppingState.loading?'正在同步…':'刷新云端清单'}}</button><van-empty v-if="!cart.rows.length&&!shoppingState.error&&!shoppingState.loading" description="清单还是空的，先收藏一点小美好吧"/><article v-for="row in cart.rows" :key="row.product.id" class="cart-row"><RouterLink :to="'/goods/'+row.product.id" @click="emit('update:show',false)"><img :src="image(row.product.image)" :alt="row.product.name"/></RouterLink><div class="cart-info"><RouterLink :to="'/goods/'+row.product.id" @click="emit('update:show',false)"><h3>{{row.product.name}}</h3></RouterLink><small>示例单价 ¥{{row.product.price.toFixed(2)}}</small><div class="cart-quantity"><div class="quantity-control"><button :aria-label="'减少 '+row.product.name" :disabled="row.quantity<=1||shoppingState.busy['cart:'+row.product.id]" @click="quantity(row.product.id,row.quantity-1)">−</button><input :aria-label="row.product.name+' 数量'" :disabled="shoppingState.busy['cart:'+row.product.id]" type="number" min="1" max="99" step="1" :value="row.quantity" @change="e=>quantity(row.product.id,Number((e.target as HTMLInputElement).value))"/><button :aria-label="'增加 '+row.product.name" :disabled="row.quantity>=99||shoppingState.busy['cart:'+row.product.id]" @click="quantity(row.product.id,row.quantity+1)">＋</button></div><button :aria-label="'移除 '+row.product.name" :disabled="shoppingState.busy['cart:'+row.product.id]" @click="setCartQuantity(row.product.id,null)">移除</button></div></div></article><div v-if="cart.rows.length" class="cart-total"><span>共 {{cart.count}} 件 · 示例合计</span><strong>¥{{cart.total.toFixed(2)}}</strong></div><p class="cart-note bottom-note">价格、商品信息均为示例。{{cloudShopping?'清单仅当前账号可见。':'清单仅保存在当前浏览器。'}}</p></section></van-popup></template>
<style scoped>.cart-sheet{padding:28px 22px calc(25px + env(safe-area-inset-bottom,0px));color:#352943}.cart-sheet h2{font-size:20px}.cart-note{font-size:11px;color:#9a86a6;margin:7px 0 18px;line-height:1.7}.cart-row{display:flex;gap:12px;padding:16px 0;border-bottom:1px solid #f0e8f5}.cart-row img{width:75px;height:85px;object-fit:cover;border-radius:14px}.cart-info{flex:1;min-width:0}.cart-info h3{font-size:13px;line-height:1.6}.cart-info small{font-size:10px;color:#c07962;display:block;margin-top:5px}.cart-quantity{display:flex;justify-content:space-between;align-items:center;gap:8px;margin-top:12px}.cart-quantity button{border:0;background:transparent;font-size:10px;color:#9a86a6;padding:6px}.cart-total{display:flex;justify-content:space-between;align-items:center;padding:18px 0 0;font-size:12px;color:#8b7b99}.cart-total strong{font-size:22px;color:#c2410c}.bottom-note{margin:16px 0 0}.quantity-control{display:flex;align-items:center;gap:2px}.quantity-control button{width:27px;height:27px;border-radius:7px;background:#f0e7f6;color:#8b6cc9;padding:0;font-size:15px}.quantity-control button:disabled{opacity:.35;cursor:default}.quantity-control input{width:35px;min-width:0;height:27px;border:0;border-radius:5px;background:#f8f4fc;text-align:center;font-size:12px;color:#7654ac;appearance:textfield}.quantity-control input::-webkit-inner-spin-button,.quantity-control input::-webkit-outer-spin-button{-webkit-appearance:none;margin:0}</style>
